select.if:
SELECT T1.TOTLE_TRADE_ID busiCode, T1.P_TRADE_ID, T1.CCY, T4.BASIS, T4.INT_RATE*100 INT_RATE, T1.COUNTER_ID, T6.COUNTER_NAME, T1.COUNTER_TRADER, T1.TRADER, T1.REMARK, T4.FINPROD_ID, T1.PORTFOLIO_ID, T2.PORTFOLIO_NAME, T5.TYPE_6,
T1.CHL_ID,
T1.FINPROD_TYPE2 , DATE_FORMAT(T1.TRADE_DATE, '%Y-%m-%d') TRADE_DATE, DATE_FORMAT(T1.VDATE, '%Y-%m-%d') vDate, DATE_FORMAT(T1.MDATE, '%Y-%m-%d') mDate, T4.TERM, T3.THEORY_PRIN, T1.TRADE_MARKET TRADE_MARKET, DATE_FORMAT(T1.SETTLE_DATE, '%Y-%m-%d') SETTLE_DATE, T3.THEORY_INT, T3.THEORY_AMT, T1.TRADE_AMT,T1.WORKFLOW_ID, T1.FPRICE_AMT, T1.FEE_AMT channelFee FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY T6 ON T1.COUNTER_ID = T6.COUNTER_ID WHERE T1.TOTLE_TRADE_ID = #{busiCode}
